/* All 100 vanilla Skulltulas; progress shared with Checks. */
(()=>{
 const colors={'Kokiri Forest':'#78ce75','Lost Woods':'#54b589','Sacred Forest Meadow':'#a3c36c','Hyrule Field':'#c8c66c','Market':'#e5bd87','Hyrule Castle':'#e4b48c','Kakariko Village':'#d6a789','Graveyard':'#b7a3d9','Death Mountain Trail':'#eea06d','Goron City':'#d9af63','Death Mountain Crater':'#f17b65','Zora River':'#72c9e9',"Zora's Domain":'#75b6f0',"Zora's Fountain":'#83dfe0','Lake Hylia':'#7ca7f0','Lon Lon Ranch':'#cdb57b','Gerudo Valley':'#d8a464','Gerudo Fortress':'#d49773',"Thieves' Hideout":'#d49773','Haunted Wasteland':'#d8c487','Desert Colossus':'#e0b97d','Deku Tree':'#91ba5d',"Dodongo's Cavern":'#edaa65',"Jabu Jabu's Belly":'#dc8d99','Forest Temple':'#62bb9c','Fire Temple':'#ef8468','Water Temple':'#739fec','Shadow Temple':'#b294df','Spirit Temple':'#e0b364','Ice Cavern':'#8fdde5','Bottom of the Well':'#b2a0c1','Gerudo Training Ground':'#c6a875',"Ganon's Castle":'#c285b8'};
 const view=document.querySelector('#view-skulls');
 const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
 const zoneAliases={'Lost Woods Maze':'Lost Woods','Market Square':'Market','Market Entrance':'Market',"Outside Ganon's Castle":"Ganon's Castle",'Castle Grounds':'Hyrule Castle'};
 const entries=window.RSL_SKULLS.map(s=>({...s,zone:s.name.startsWith('OGC ')?"Ganon's Castle":zoneAliases[s.zone]??s.zone}));
 const isDone=s=>state.checks?.done?.[s.name]===true;
 const short=name=>name.replace(/^(?:KF|LW|SFM|HF|LLR|LH|GV|GF|GC|DMT|DMC|ZR|ZD|ZF|Kak|HC|OGC|Market|Graveyard|Deku Tree|Dodongos Cavern|Jabu Jabus Belly|Forest Temple|Fire Temple|Water Temple|Shadow Temple|Spirit Temple|Ice Cavern|Bottom of the Well) GS /,'');
 const tools=make('div','skull-tools'),count=make('strong'),label=make('label'),remaining=make('input');remaining.type='checkbox';label.append(remaining,document.createTextNode('Restantes uniquement'));tools.append(count,label);const grid=make('div','checks-zones');view.append(tools,grid);remaining.addEventListener('change',render);
 function render(){const total=entries.filter(isDone).length;count.textContent=total+' / 100 emplacements faits · '+(100-total)+' restants';grid.replaceChildren();const zones=new Map();for(const s of entries){if(!zones.has(s.zone))zones.set(s.zone,[]);zones.get(s.zone).push(s);}const order=Object.keys(colors);for(const [zone,all] of [...zones].sort(([a],[b])=>(order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b)))){const shown=all.filter(s=>!remaining.checked||!isDone(s)).sort((a,b)=>Number(isDone(a))-Number(isDone(b)));if(!shown.length)continue;const card=make('section','checks-zone'),head=make('div','checks-zone-head');card.style.setProperty('--zone',colors[zone]??'#99bac1');head.append(make('h2','',zone),make('span','',all.filter(isDone).length+' / '+all.length));card.append(head);for(const s of shown){const row=make('label','available-check'),box=make('input');box.type='checkbox';box.checked=isDone(s);box.dataset.skull=s.name;box.setAttribute('aria-label',s.name+' faite');row.title=s.name;box.addEventListener('change',()=>{state.checks??={inventory:{},done:{},startAge:'child'};state.checks.done??={};state.checks.done[s.name]=box.checked;save();});row.append(box,make('span','check-name',short(s.name)));card.append(row);}grid.append(card);}if(!grid.children.length)grid.append(make('p','checks-empty','Toutes les Skulltulas sont cochées.'));}
 window.addEventListener('rsl-view',e=>{if(e.detail==='skulls')render();});window.addEventListener('rsl-save',()=>{if(!view.hidden)render();});render();
})();
